      "id": "surface",
      "title": "3D",
      "headline": "A shaded 3D surface, projected by Ostrin.",
      "file": "examples/lab_surface.ostrin",
      "render": "svg",
      "params": [
        {
          "name": "waves",
          "label": "Wave number k",
          "min": 0.4,
          "max": 3,
          "step": 0.1
        },
        {
          "name": "azimuth",
          "label": "Azimuth (°)",
          "min": -90,
          "max": 0,
          "step": 5
        },
        {
          "name": "elevation",
          "label": "Elevation (°)",
          "min": 10,
          "max": 70,
          "step": 5
        }
      ],
      "how": "Ostrin samples z = cos(k r) exp(-r/4) on a 28 × 28 grid; std.viz rotates it with an orthographic camera, sorts 1458 triangles back to front, shades each one with a directional light and maps its height to the magma colormap.",
      "docs": {
        "label": "std.viz source",
        "href": "https://github.com/sircalch/Ostrin/blob/main/compiler/std/viz.ostrin"
      },
      "limits": "Rendering is CPU-side SVG (painter's algorithm), fine for thousands of triangles. A WebGPU backend for large meshes and volumes is planned.",
      "files": {
        "main.ostrin": "// Scientific Lab · 3D\n// A ripple surface z = cos(k r) exp(-r / 4), shaded and projected by std.viz.\nimport std.viz\n\nfn main() -> Void {\n    waves = 1.6\n    azimuth = -50.0\n    elevation = 32.0\n    xs = linspace(-8.0, 8.0, 28)\n    mut z = zeros([28, 28])\n    for i in 0 until 28 {\n        for j in 0 until 28 {\n            r = sqrt(xs[i] * xs[i] + xs[j] * xs[j])\n            z.set(i, j, cos(r * waves) * exp(-r / 4.0))\n        }\n    }\n    print(\"z range: \" + viz.num(z.min()) + \" to \" + viz.num(z.max()))\n    scene = viz.scene3d(\"Ripple, k = \" + waves.to_string())\n        .labels(\"x\", \"y\", \"z\")\n        .view(azimuth, elevation)\n        .surface(xs, xs, z, colormap: \"magma\", label: \"z\")\n    print(scene.svg())\n}\n"
      },
      "main": "main.ostrin",
      "args": [
        "--run",
        "main.ostrin"
      ],
      "source": "examples/lab_surface.ostrin",
