      "limits": "The generator is deterministic and seedable; parallel random streams are planned.",
      "files": {
        "main.ostrin": "// Scientific Lab · Monte Carlo\n// Estimate pi from uniformly random points in the unit square, with a seeded generator.\nfn main() -> Void {\n    seed = 2024\n    samples = 20000\n    checkpoints = 10\n    g = rng(seed)\n    points = g.rand([samples, 2])\n\n    mut hits = 0\n    mut i = 0\n    every = samples / checkpoints\n    while i < samples {\n        x = points.get(i, 0)\n        y = points.get(i, 1)\n        if x * x + y * y < 1.0 {\n            hits = hits + 1\n        }\n        i = i + 1\n        if i % every == 0 {\n            estimate = 4.0 * (hits as Float) / (i as Float)\n            print(\"estimate \" + i.to_string() + \" \" + (round(estimate * 100000.0) / 100000.0).to_string())\n        }\n    }\n\n    result = 4.0 * (hits as Float) / (samples as Float)\n    print(\"pi ≈ \" + (round(result * 100000.0) / 100000.0).to_string())\n    print(\"|error| = \" + (round(abs(result - pi()) * 100000.0) / 100000.0).to_string())\n    print(\"expected standard error ≈ \" + (round(4.0 * sqrt(pi() / 4.0 * (1.0 - pi() / 4.0) / (samples as Float)) * 100000.0) / 100000.0).to_string())\n}\n"
      },
